import{_ as o,a as r,b as a,c as i,d as s,e as l}from"./chunks/site-tools-options.CSfW-Ynq.js";import{_ as e,o as n,c as g,a2 as p}from"./chunks/framework.CfwCq2QB.js";const I=JSON.parse('{"title":"站点工具与录制操作","description":"","frontmatter":{},"headers":[],"relativePath":"features/site-tools.md","filePath":"features/site-tools.md"}'),m={name:"features/site-tools.md"};function c(d,t,h,u,_,f){return n(),g("div",null,[...t[0]||(t[0]=[p('<h1 id="站点工具与录制操作" tabindex="-1">站点工具与录制操作 <a class="header-anchor" href="#站点工具与录制操作" aria-label="Permalink to &quot;站点工具与录制操作&quot;">​</a></h1><p>一句话：给任意网站加上 AI 助手能调用的工具，比如「搜索本站商品」「读取订单列表」「填好表单并提交」。可以让 AI 看着网页帮你生成，也可以把自己的操作录一遍；保存后既能一键重放，也能在对话里让 AI 自动调用。</p><p>和<a href="/dev-go-docs/features/webmcp.html">网页工具（WebMCP）</a>的区别：WebMCP 工具是网站自己提供的，绝大多数网站还没有；站点工具是你自己给网站加的，任何网站都能用，也不需要开启浏览器的实验功能。</p><h2 id="方式一-让-ai-生成" tabindex="-1">方式一：让 AI 生成 <a class="header-anchor" href="#方式一-让-ai-生成" aria-label="Permalink to &quot;方式一：让 AI 生成&quot;">​</a></h2><ol><li>打开想增强的网站，打开侧边栏（<code>Alt+2</code>），切到「<strong>网页工具</strong>」页</li><li>当前网站还没有工具时，页面上直接就是「想要一个什么工具？」输入框；已经有工具时点「<strong>用 AI 新建工具</strong>」</li><li>描述需求，或者点下面的示例（「搜索本站内容，返回标题和链接」「读取当前页面的列表数据」等），点「<strong>开始创建</strong>」</li><li>对话里能看到 AI 的过程：<strong>查看网页结构</strong> → 写出工具 → <strong>试运行</strong>，出错会自己修正</li><li>保存前会弹出确认卡片，展示完整的工具定义，你点「允许执行」才会保存</li></ol><img src="'+o+'" alt="侧边栏「网页工具」页的空状态：「这个网页还没有工具」说明和「想要一个什么工具？」输入框、三个示例、「开始创建」按钮" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：「网页工具」页——没有工具时直接描述需求，让 AI 创建。</em></p><p>也可以直接在「对话」里说「给这个网站做一个搜索工具」，效果一样。</p><h2 id="方式二-录制操作" tabindex="-1">方式二：录制操作 <a class="header-anchor" href="#方式二-录制操作" aria-label="Permalink to &quot;方式二：录制操作&quot;">​</a></h2><p>适合「点这里、选那个、填好再提交」这类流程化操作——你亲手做一遍，步骤是确定的，不依赖 AI，没配置模型也能用。</p><p><strong>开始录制</strong>：弹窗「功能」页的「<strong>录制操作</strong>」点「开始录制」，或者侧边栏「网页工具」页点「<strong>录制操作</strong>」。</p><img src="'+r+'" alt="弹窗「功能」页的「录制操作」一行，右侧是带红点的「开始录制」按钮" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：弹窗「功能」页的「录制操作」入口。</em></p><p><strong>录制中</strong>：网页顶部出现录制条，正常操作网页即可：</p><ul><li>点击、输入、勾选、下拉选择、回车都会被记录；同一个输入框连续输入只记最终的值</li><li>跳转到其他页面也会接着录（如「首页 → 登录页 → 账户页」）</li><li>想让工具返回数据时，点录制条上的「<strong>选取数据</strong>」，再点页面上要读的内容，选择「读取这一项」或「读取整个列表（N 项）」——同类的列表项会自动识别</li><li>点「<strong>完成</strong>」结束（也可以在弹窗里点「完成录制」），点「取消」放弃</li></ul><img src="'+a+'" alt="录制中的网页：顶部是「录制中 · 5 步 / 选取数据 / 取消 / 完成」录制条，选中了订单列表中的一项，弹出「读取这一项 / 读取整个列表（3 项）」"><p><em>图：录制条与「选取数据」——点中订单列表的一项，可以读取这一项或整个列表。</em></p><p><strong>整理保存</strong>：录完侧边栏会打开整理页：</p><ul><li>每个填写的值旁边可以勾「<strong>设为参数</strong>」，下次执行就能换成别的值（如搜索关键词、用户名）</li><li>改工具名、用途说明（AI 据此判断什么时候调用）和生效网址</li><li>「<strong>只读</strong>」：只读取、不改动网站数据的流程打开它，执行前就不再确认（默认关）</li><li>「<strong>先打开录制开始的网址</strong>」：每次执行先跳到录制起点再操作（默认关，在当前页面上执行）</li><li>多余的步骤可以删掉；点「<strong>试运行</strong>」验证（试运行总是先回到录制开始的网址），再「<strong>保存</strong>」</li></ul><img src="'+i+'" alt="录制整理页：工具名、用途说明、生效网址、只读与先打开录制开始的网址两个开关，下面是 6 个步骤，用户名勾选了设为参数，密码未录制、作为参数传入" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：录制整理页——用户名设为参数，密码没有录下、执行时传入。</em></p><h3 id="密码" tabindex="-1">密码 <a class="header-anchor" href="#密码" aria-label="Permalink to &quot;密码&quot;">​</a></h3><p>默认<strong>不录密码</strong>：录到的密码框会自动变成参数，执行时再传入。如果为了方便确实想把密码存下来，在设置页「AI 助手 → 站点工具」打开「<strong>录制时保存密码</strong>」——打开后密码会明文存在本机的工具定义里，也会进入备份导出文件，请自行权衡。</p><h2 id="使用工具" tabindex="-1">使用工具 <a class="header-anchor" href="#使用工具" aria-label="Permalink to &quot;使用工具&quot;">​</a></h2><ul><li><strong>让 AI 调用</strong>：在这个网站上直接说需求，比如「帮我搜一下有哪些键盘，按价格从低到高列出来」，AI 会自动调用匹配当前网址的站点工具</li><li><strong>手动执行</strong>：侧边栏「网页工具」页里，站点工具带「站点工具」标签，展开卡片填参数、点「执行」</li></ul><img src="'+s+'" alt="侧边栏对话：用户请求搜索键盘，AI 调用 search_products 工具后用表格列出 3 个商品的价格和链接" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：对话里 AI 调用站点工具，结果整理成表格。</em></p><p>会修改数据的工具（没标只读的）执行前会弹卡片让你确认，和网页工具的确认是同一个开关（设置页「AI 助手」）。</p><h2 id="管理、导入与导出" tabindex="-1">管理、导入与导出 <a class="header-anchor" href="#管理、导入与导出" aria-label="Permalink to &quot;管理、导入与导出&quot;">​</a></h2><p>设置页「<strong>AI 助手 → 站点工具</strong>」里列出全部站点工具，可以：</p><ul><li>启用 / 停用、编辑（JSON）、删除</li><li><strong>导出</strong>单个工具为 JSON 文件，分享给别人</li><li><strong>导入</strong> DevGo 导出的工具，或 <strong>Chrome 开发者工具「Recorder」面板</strong>导出的 JSON 录制——已有的录制可以直接变成站点工具</li></ul><p>站点工具会随<a href="/dev-go-docs/settings/sync.html">备份</a>一起导出 / 导入。</p><img src="'+l+'" alt="设置页「站点工具」卡片：导入、新建按钮，一个导入的录制工具（带启用开关、编辑、导出、删除按钮），下方是「录制时保存密码」开关"><p><em>图：设置页「站点工具」——导入 / 导出、启停与「录制时保存密码」开关。</em></p><h2 id="工作原理与限制" tabindex="-1">工作原理与限制 <a class="header-anchor" href="#工作原理与限制" aria-label="Permalink to &quot;工作原理与限制&quot;">​</a></h2><ul><li>工具是<strong>纯数据</strong>：一组参数加一串固定步骤（请求接口、填写、按键、点击、等待、读取、打开网址），由 DevGo 内置的执行器执行，<strong>不运行任何代码</strong>，不需要额外权限，GitHub 这类安全策略严格的网站也能用</li><li>每个元素会记下 3–5 个候选选择器（按名称、属性、文字、路径），网站小改版时会自动换用备选；点击、填写前会自动等待元素出现</li><li>支持跨页面：点击或打开网址导致页面跳转后，等新页面加载完再继续后面的步骤</li><li>扩展刚安装或更新、网页还没刷新时也能直接执行，不用手动刷新</li><li>暂不支持：iframe 内的元素、拖拽 / 悬停 / 滚动；网站大改版后选择器可能失效，这时让 AI「修一下这个工具」，或重新录制</li><li>生效网址写域名（<code>github.com</code>，含子域名）或带路径的通配（<code>github.com/*/issues*</code>），只在匹配的网站上出现</li></ul>',36)])])}const q=e(m,[["render",c]]);export{I as __pageData,q as default};
